use vstd::prelude::*;

verus! {
    fn to_uppercase(str1: &Vec<char>) -> (result: Vec<char>)
        requires
            str1.len() <= 0xFFFF, // Assuming a reasonable upper limit for the length of the vector
        ensures
            result.len() == str1.len(),
            forall|i: nat| 0 <= i < str1.len() ==> 
                (if 'a' <= str1[i] && str1[i] <= 'z' {
                    result[i] == (str1[i] as u8 - 32) as char // Convert to uppercase
                } else {
                    result[i] == str1[i]
                }),
    {
        let mut result: Vec<char> = Vec::new();
        let mut idx: usize = 0;

        while idx < str1.len()
            invariant
                idx <= str1.len(),
                result.len() == idx,
                forall|j: nat| 0 <= j < idx ==> 
                    (if 'a' <= str1[j] && str1[j] <= 'z' {
                        result[j] == (str1[j] as u8 - 32) as char
                    } else {
                        result[j] == str1[j]
                    }),
            decreases str1.len() - idx,
        {
            let c = str1[idx];
            if 'a' <= c && c <= 'z' {
                result.push((c as u8 - 32) as char); // Convert to uppercase
            } else {
                result.push(c); // Keep the character unchanged
            }
            idx = idx + 1;
        }
        result
    }
}
